(function(){"use strict";var grid=document.getElementById("fleet-car-grid");var button=document.querySelector(".pr-fleet-more");if(!grid||!button)return;var count=button.querySelector(".pr-fleet-more-n");var SHOWN=6;function cars(){return grid.querySelectorAll(".de-item").length}function update(){var n=cars();if(count)count.textContent=n?"("+n+")":"";button.classList.toggle("is-needed",n>SHOWN&&!grid.classList.contains("is-expanded"))}button.addEventListener("click",function(){grid.classList.add("is-expanded");button.setAttribute("aria-expanded","true");update();var next=grid.children[SHOWN];if(next){var a=next.querySelector("a, button");if(a)a.focus({preventScroll:true})}});new MutationObserver(update).observe(grid,{childList:true});update()})();